package com.garmentstore.auth.domain;
import com.garmentstore.common.domain.BaseEntity; import jakarta.persistence.*; import lombok.*; import java.time.Instant;
@Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor @Entity @Table(name="refresh_tokens", indexes={@Index(name="idx_refresh_tokens_user",columnList="user_id"),@Index(name="idx_refresh_tokens_hash",columnList="token_hash"),@Index(name="idx_refresh_tokens_status",columnList="status")}) public class RefreshToken extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="token_hash",nullable=false,unique=true,length=128) private String tokenHash; @Enumerated(EnumType.STRING) @Column(name="status",nullable=false,length=30) private RefreshTokenStatus status; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="revoked_at") private Instant revokedAt; @Column(name="replaced_by_token_id") private Long replacedByTokenId; @Column(name="ip_address",length=80) private String ipAddress; @Column(name="user_agent",length=500) private String userAgent; }
